BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL statement_timeout='30s';
WITH v AS MATERIALIZED (SELECT id,slug,hidden,seating_area,seating_elevation_m,ground_elevation_m,updated_at FROM public.venues WHERE deleted_at IS NULL),
centers AS MATERIALIZED (SELECT v.*,c.lat,c.lng FROM v CROSS JOIN LATERAL (SELECT avg((p.value->>1)::float8) AS lat,avg((p.value->>0)::float8) AS lng FROM jsonb_array_elements(v.seating_area->'coordinates'->0) WITH ORDINALITY p(value,ord) WHERE p.ord<=jsonb_array_length(v.seating_area->'coordinates'->0)-CASE WHEN v.seating_area->'coordinates'->0->0=v.seating_area->'coordinates'->0->-1 THEN 1 ELSE 0 END) c),
resolved AS MATERIALIZED (SELECT c.id AS venue_id,to_jsonb(b) AS caster FROM centers c CROSS JOIN LATERAL public.get_buildings_near_point(c.lat,c.lng,200) b),
unique_casters AS (SELECT DISTINCT caster FROM resolved)
SELECT jsonb_build_object('capturedAt',clock_timestamp(),'snapshot',pg_current_snapshot()::text,'selection','get_buildings_near_point with nonduplicated outer-ring mean, 200m; non-deleted venues','counts',jsonb_build_object('venues',(SELECT count(*) FROM v),'uniqueCasters',(SELECT count(*) FROM unique_casters),'casterReferences',(SELECT count(*) FROM resolved)),'venues',(SELECT jsonb_agg(to_jsonb(c)||jsonb_build_object('casterIds',COALESCE((SELECT jsonb_agg((r.caster->>'Id')::bigint ORDER BY (r.caster->>'Id')::bigint) FROM resolved r WHERE r.venue_id=c.id),'[]'::jsonb)) ORDER BY c.id) FROM centers c),'casters',(SELECT jsonb_agg(caster ORDER BY (caster->>'Id')::bigint) FROM unique_casters),'rpcDefinition',(SELECT pg_get_functiondef(p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='get_buildings_near_point' LIMIT 1)) AS capture; COMMIT;
